  r += textureGrad(uTex, vec2(c12.x, c12.y), gx, gy).rgb * w12.x * w12.y;
  r += textureGrad(uTex, vec2(c3.x, c12.y), gx, gy).rgb * w3.x * w12.y;
  r += textureGrad(uTex, vec2(c0.x, c3.y), gx, gy).rgb * w0.x * w3.y;
